get_animation_effects.code:
use WebCommander\Sdk\Resources\Settings\AnimationEffects\AnimationEffects;

$response = AnimationEffects::getAnimationEffects($client);

$settings = $response->map['animation_effects'];
echo 'preloader: ', $settings['preloader_design']['preloader_preset'], PHP_EOL;
echo 'page transition: ', $settings['page_transition']['page_transition_animation_type'], PHP_EOL;

patch_animation_effects.code:
use WebCommander\Sdk\Resources\Settings\AnimationEffects\AnimationEffects;

$response = AnimationEffects::patchAnimationEffects($client, [
    'animation_effects' => [
        'page_transition' => ['animation_before_entering_new_page' => true],
        'image_lazy_effect' => ['blog_list_image_lazy_effect' => true],
    ],
]);

$settings = $response->map['animation_effects'];
echo $settings['page_transition']['animation_before_entering_new_page'] ? 'true' : 'false', PHP_EOL;
echo $settings['image_lazy_effect']['blog_list_image_lazy_effect'] ? 'true' : 'false', PHP_EOL;

get_animation_effects_section.code:
use WebCommander\Sdk\Resources\Settings\AnimationEffects\AnimationEffects;

$response = AnimationEffects::getAnimationEffectsSection($client, 'widget_transition');

$section = $response->map['widget_transition'];
echo 'smooth render: ', $section['widget_smooth_render'] ? 'on' : 'off', PHP_EOL;
echo $section['widget_smooth_render_duration'], ' ms', PHP_EOL;
